<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SalesOrderItem extends Model { use HasUuids; protected $fillable=['tenant_id','sales_order_id','variant_id','preferred_location_id','warehouse_id','description','unit','ordered_quantity','reserved_quantity','backordered_quantity','delivered_quantity','returned_quantity','invoiced_quantity','unit_price','discount_type','discount_rate','tax_rate','tax_code','line_subtotal','discount_amount','tax_amount','line_total']; protected function casts(): array { return ['ordered_quantity'=>'decimal:6','reserved_quantity'=>'decimal:6','backordered_quantity'=>'decimal:6','delivered_quantity'=>'decimal:6','returned_quantity'=>'decimal:6','invoiced_quantity'=>'decimal:6','unit_price'=>'decimal:6','discount_rate'=>'decimal:6','tax_rate'=>'decimal:6','line_subtotal'=>'decimal:6','discount_amount'=>'decimal:6','tax_amount'=>'decimal:6','line_total'=>'decimal:6']; } public function order(){return $this->belongsTo(SalesOrder::class,'sales_order_id');} public function variant(){return $this->belongsTo(ProductVariant::class);} public function reservations(){return $this->hasMany(StockReservation::class,'sales_order_item_id');} }
